#!/usr/bin/env python3
"""Format Dependabot changelog entries in CHANGELOG.md to match repository conventions."""

import argparse
import re
import sys
from pathlib import Path

# Match Dependabot entries generated by the workflow pattern:
# - Bump `[dep](url)` from [old] to [new] [#pr](url) @dependabot
# or already formatted:
# - Bump [`dep`](url) from [old] to [new] [\#pr](url) @dependabot
# or plain dependency names:
# - Bump `dep` from [old] to [new] [#pr](url) @dependabot
DEPENDABOT_ENTRY_PATTERN = re.compile(
    r"^- Bump .+ from .+ to .+ \[\\?#\d+\]\([^)]+\) @dependabot$"
)


def is_dependabot_entry(entry: str) -> bool:
    """Check if an item is a Dependabot changelog entry."""
    first_line = entry.splitlines()[0] if entry.splitlines() else entry
    return bool(DEPENDABOT_ENTRY_PATTERN.match(first_line.strip()))


def format_dependabot_item(item: str) -> str:
    """Format an individual Dependabot entry to match repo conventions."""
    # Convert `[dep](url)` to [`dep`](url) while leaving plain `dep` untouched
    s = re.sub(r"`\[([^\]]+)\]\(([^)]+)\)`", r"[`\1`](\2)", item)
    # Escape unescaped PR link hashes [#123](url) -> [\#123](url)
    s = re.sub(r"(?<!\\)\[#(\d+)\]\(([^)]+)\)", r"[\#\1](\2)", s)
    return s


def format_maintenance_section(section_text: str) -> str:
    """Format and deduplicate Dependabot entries in the Maintenance section."""
    lines = section_text.splitlines()
    header_lines: list[str] = []
    items: list[str] = []
    current_item: list[str] = []
    in_items = False

    for line in lines:
        if line.startswith("- "):
            in_items = True
            if current_item:
                items.append("\n".join(current_item).strip())
                current_item = []
            current_item.append(line)
        elif in_items:
            current_item.append(line)
        else:
            header_lines.append(line)

    if current_item:
        items.append("\n".join(current_item).strip())

    while header_lines and not header_lines[-1].strip():
        header_lines.pop()

    seen_dependabot_entries: set[str] = set()
    unique_items: list[str] = []
    for item in items:
        if is_dependabot_entry(item):
            formatted_item = format_dependabot_item(item)
            if formatted_item in seen_dependabot_entries:
                continue
            seen_dependabot_entries.add(formatted_item)
            unique_items.append(formatted_item)
        else:
            # Human entries are preserved exactly as written
            unique_items.append(item)

    header = "\n".join(header_lines)
    if unique_items:
        return f"{header}\n\n" + "\n\n".join(unique_items) + "\n\n"
    return f"{header}\n\n"


def format_changelog(content: str) -> str:
    """Format the Maintenance section under the unreleased version in the changelog."""
    # Locate ## [unreleased]
    unreleased_match = re.search(
        r"^##\s+\[unreleased\](?:\([^)]+\))?\s*$",
        content,
        re.IGNORECASE | re.MULTILINE,
    )
    if not unreleased_match:
        return content

    unreleased_start = unreleased_match.start()

    # Find the next H2 header after unreleased
    after_unreleased = content[unreleased_start + len(unreleased_match.group()) :]
    next_h2_match = re.search(r"^##\s+", after_unreleased, re.MULTILINE)
    if next_h2_match:
        unreleased_end = (
            unreleased_start + len(unreleased_match.group()) + next_h2_match.start()
        )
    else:
        unreleased_end = len(content)

    unreleased_content = content[unreleased_start:unreleased_end]

    # Locate ### Maintenance within unreleased section (exact heading, no asterisk)
    maint_match = re.search(
        r"(^###\s+Maintenance[^\S\r\n]*\r?\n)(.*?)(?=^### |\Z)",
        unreleased_content,
        re.DOTALL | re.MULTILINE,
    )
    if not maint_match:
        return content

    maint_header = maint_match.group(1)
    maint_body = maint_match.group(2)
    formatted_maint = format_maintenance_section(maint_header + maint_body)

    new_unreleased = (
        unreleased_content[: maint_match.start()]
        + formatted_maint
        + unreleased_content[maint_match.end() :]
    )

    return content[:unreleased_start] + new_unreleased + content[unreleased_end:]


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Format Dependabot changelog entries in CHANGELOG.md."
    )
    parser.add_argument(
        "changelog",
        nargs="?",
        default="CHANGELOG.md",
        help="Path to CHANGELOG.md (default: CHANGELOG.md)",
    )
    args = parser.parse_args()

    changelog_path = Path(args.changelog)
    if not changelog_path.is_file():
        print(f"Error: Changelog file '{changelog_path}' not found.", file=sys.stderr)
        return 1

    content = changelog_path.read_text(encoding="utf-8")
    formatted = format_changelog(content)

    if formatted != content:
        changelog_path.write_text(formatted, encoding="utf-8")
        print(f"Formatted Dependabot entries in '{changelog_path}'.")
    else:
        print(f"No formatting changes needed in '{changelog_path}'.")

    return 0


if __name__ == "__main__":
    sys.exit(main())
